1	/* ==========================================================================
2	   PLANETFALL × ENTIRE.IO — UI THEME
3	   Drop this file into your project and import it before your game styles.
4	   All game UI (menus, HUD, terminal, overlays) inherits from these tokens.
5	   ========================================================================== */
6	
7	/* --------------------------------------------------------------------------
8	   FONTS — add this @import at the very top of your main CSS entry point
9	   -------------------------------------------------------------------------- */
10	@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=Space+Mono:ital,wght@0,400;0,700;1,400&display=swap');
11	
12	/* --------------------------------------------------------------------------
13	   TOKENS
14	   -------------------------------------------------------------------------- */
15	:root {
16	
17	  /* Palette ---------------------------------------------------------------- */
18	  --color-bg:             #0D0E1F;   /* page / canvas backdrop             */
19	  --color-surface:        #12132A;   /* cards, HUD panels, menu backgrounds */
20	  --color-surface-raised: #1A1B3E;   /* elevated surfaces, dropdowns        */
21	  --color-well:           #080910;   /* terminal, deeply inset areas        */
22	
23	  --color-purple:         #6B5FD4;   /* primary action, borders, rings      */
24	  --color-purple-bright:  #8B7FE8;   /* secondary labels, icons             */
25	  --color-purple-dim:     #534AB7;   /* hover state for purple elements     */
26	  --color-purple-glow:    #2B2D6E;   /* subtle backgrounds, selection bg    */
27	
28	  --color-accent:         #00E5C4;   /* timers, CTAs, beam highlights, live */
29	  --color-accent-dim:     #00B39A;   /* hover state for accent elements     */
30	
31	  --color-text-primary:   #F0EEF8;   /* headings, values, active labels     */
32	  --color-text-secondary: rgba(240, 238, 248, 0.6);  /* body, descriptions  */
33	  --color-text-muted:     rgba(240, 238, 248, 0.3);  /* hints, timestamps   */
34	
35	  --color-success:        #6EE7B7;   /* correct input, transmission OK      */
36	  --color-warning:        #F5C440;   /* gold rank, time running low         */
37	  --color-danger:         #E24B4A;   /* time up, system error               */
38	
39	  --color-border:         rgba(107, 95, 212, 0.25);  /* default borders     */
40	  --color-border-strong:  rgba(107, 95, 212, 0.5);   /* focused / hover     */
41	  --color-border-accent:  rgba(0, 229, 196, 0.4);    /* accent-adjacent     */
42	
43	  /* Typography ------------------------------------------------------------- */
44	  --font-display: 'Space Mono', 'Courier New', monospace;
45	  --font-ui:      'Space Grotesk', system-ui, sans-serif;
46	  --font-terminal:'Space Mono', 'Courier New', monospace;
47	
48	  /* Type scale */
49	  --text-xs:   10px;
50	  --text-sm:   12px;
51	  --text-base: 14px;
52	  --text-md:   16px;
53	  --text-lg:   20px;
54	  --text-xl:   28px;
55	  --text-2xl:  40px;
56	  --text-3xl:  56px;
57	
58	  /* Letter spacing */
59	  --tracking-tight:  0.02em;
60	  --tracking-normal: 0.05em;
61	  --tracking-wide:   0.12em;
62	  --tracking-wider:  0.2em;
63	
64	  /* Spacing ---------------------------------------------------------------- */
65	  --space-1:  4px;
66	  --space-2:  8px;
67	  --space-3:  12px;
68	  --space-4:  16px;
69	  --space-5:  20px;
70	  --space-6:  24px;
71	  --space-8:  32px;
72	  --space-10: 40px;
73	
74	  /* Radii ------------------------------------------------------------------ */
75	  --radius-sm: 2px;   /* buttons, tags — sharp/angular feel  */
76	  --radius-md: 4px;   /* cards, panels                       */
77	  --radius-lg: 8px;   /* modals, larger containers           */
78	  --radius-pill: 20px;/* badges                              */
79	
80	  /* Transitions ------------------------------------------------------------ */
81	  --ease-fast:   0.15s ease;
82	  --ease-normal: 0.25s ease;
83	  --ease-slow:   0.4s ease;
84	
85	  /* Z-layers --------------------------------------------------------------- */
86	  --z-hud:     10;
87	  --z-overlay: 20;
88	  --z-modal:   30;
89	  --z-top:     40;
90	}
91	
92	
93	/* --------------------------------------------------------------------------
94	   BASE RESET — scoped to the game UI root
95	   Apply class="pf-ui" to your top-level overlay container
96	   -------------------------------------------------------------------------- */
97	.pf-ui,
98	.pf-ui * {
99	  box-sizing: border-box;
100	  margin: 0;
101	  padding: 0;
102	}
103	
104	.pf-ui {
105	  font-family: var(--font-ui);
106	  font-size: var(--text-base);
107	  color: var(--color-text-primary);
108	  background: transparent;
109	  line-height: 1.5;
110	  -webkit-font-smoothing: antialiased;
111	}
112	
113	
114	/* --------------------------------------------------------------------------
115	   TYPOGRAPHY UTILITIES
116	   -------------------------------------------------------------------------- */
117	
118	/* Display — game title, level announcements */
119	.pf-title {
120	  font-family: var(--font-display);
121	  font-size: var(--text-3xl);
122	  font-weight: 700;
123	  letter-spacing: var(--tracking-wide);
124	  text-transform: uppercase;
125	  color: var(--color-text-primary);
126	  line-height: 1;
127	}
128	
129	.pf-title .accent { color: var(--color-accent); }
130	
131	/* Section headers / screen names */
132	.pf-heading {
133	  font-family: var(--font-display);
134	  font-size: var(--text-lg);
135	  font-weight: 700;
136	  letter-spacing: var(--tracking-wide);
137	  text-transform: uppercase;
138	  color: var(--color-text-primary);
139	}
140	
141	/* HUD labels — TIME REMAINING, SIGNAL STRENGTH etc */
142	.pf-label {
143	  font-family: var(--font-display);
144	  font-size: var(--text-xs);
145	  font-weight: 400;
146	  letter-spacing: var(--tracking-wider);
147	  text-transform: uppercase;
148	  color: var(--color-purple-bright);
149	}
150	
151	/* HUD values — the big number */
152	.pf-value {
153	  font-family: var(--font-display);
154	  font-size: var(--text-xl);
155	  font-weight: 700;
156	  color: var(--color-text-primary);
157	  line-height: 1;
158	}
159	
160	.pf-value.accent { color: var(--color-accent); }
161	
162	/* Body text */
163	.pf-body {
164	  font-family: var(--font-ui);
165	  font-size: var(--text-base);
166	  color: var(--color-text-secondary);
167	  line-height: 1.7;
168	}
169	
170	/* Muted / hints */
171	.pf-muted {
172	  font-family: var(--font-display);
173	  font-size: var(--text-sm);
174	  color: var(--color-text-muted);
175	  letter-spacing: var(--tracking-normal);
176	}
177	
178	/* Terminal text */
179	.pf-mono {
180	  font-family: var(--font-terminal);
181	  font-size: var(--text-sm);
182	  line-height: 1.9;
183	}
184	
185	
186	/* --------------------------------------------------------------------------
187	   BUTTONS
188	   -------------------------------------------------------------------------- */
189	
190	/* Primary — START GAME, CONFIRM, TRANSMIT */
191	.pf-btn {
192	  display: inline-flex;
193	  align-items: center;
194	  justify-content: center;
195	  gap: var(--space-2);
196	  font-family: var(--font-display);
197	  font-size: var(--text-sm);
198	  font-weight: 700;
199	  letter-spacing: var(--tracking-wide);
200	  text-transform: uppercase;
201	  padding: 13px 32px;
202	  background: var(--color-purple);
203	  color: var(--color-text-primary);
204	  border: none;
205	  border-radius: var(--radius-sm);
206	  cursor: pointer;
207	  transition: background var(--ease-fast);
208	  /* angled clip — signature game-button shape */
209	  clip-path: polygon(10px 0%, 100% 0%, calc(100% - 10px) 100%, 0% 100%);
210	  white-space: nowrap;
211	  user-select: none;
212	}
213	
214	.pf-btn:hover  { background: var(--color-purple-bright); }
215	.pf-btn:active { background: var(--color-purple-dim); transform: scale(0.98); }
216	
217	/* Secondary — LEADERBOARD, BACK, OPTIONS */
218	.pf-btn-ghost {
219	  display: inline-flex;
220	  align-items: center;
221	  justify-content: center;
222	  gap: var(--space-2);
223	  font-family: var(--font-display);
224	  font-size: var(--text-sm);
225	  font-weight: 400;
226	  letter-spacing: var(--tracking-wide);
227	  text-transform: uppercase;
228	  padding: 12px 24px;
229	  background: transparent;
230	  color: var(--color-accent);
231	  border: 1px solid var(--color-accent);
232	  border-radius: var(--radius-sm);
233	  cursor: pointer;
234	  transition: background var(--ease-fast), color var(--ease-fast);
235	  white-space: nowrap;
236	  user-select: none;
237	}
238	
239	.pf-btn-ghost:hover  { background: rgba(0, 229, 196, 0.08); }
240	.pf-btn-ghost:active { background: rgba(0, 229, 196, 0.15); transform: scale(0.98); }
241	
242	/* Danger — TIME'S UP, ABORT */
243	.pf-btn-danger {
244	  background: var(--color-danger);
245	  color: #fff;
246	}
247	.pf-btn-danger:hover { background: #f06060; }
248	
249	
250	/* --------------------------------------------------------------------------
251	   PANELS & CARDS
252	   -------------------------------------------------------------------------- */
253	
254	/* General surface panel */
255	.pf-panel {
256	  background: var(--color-surface);
257	  border: 1px solid var(--color-border);
258	  border-radius: var(--radius-md);
259	  padding: var(--space-4);
260	  position: relative;
261	}
262	
263	/* Top-accent stripe — use with .pf-panel */
264	.pf-panel::before {
265	  content: '';
266	  position: absolute;
267	  top: 0; left: 0; right: 0;
268	  height: 2px;
269	  border-radius: var(--radius-md) var(--radius-md) 0 0;
270	  background: var(--color-purple);
271	}
272	
273	.pf-panel.accent-top::before { background: var(--color-accent); }
274	.pf-panel.no-stripe::before  { display: none; }
275	
276	/* HUD card — compact stat tile */
277	.pf-hud-card {
278	  background: var(--color-surface);
279	  border: 1px solid var(--color-border);
280	  border-radius: var(--radius-md);
281	  padding: var(--space-4);
282	  position: relative;
283	  overflow: hidden;
284	}
285	
286	.pf-hud-card::before {
287	  content: '';
288	  position: absolute;
289	  top: 0; left: 0; right: 0;
290	  height: 2px;
291	  background: var(--color-purple);
292	}
293	
294	.pf-hud-card.critical::before { background: var(--color-accent); }
295	
296	/* Modal / full overlay */
297	.pf-modal-backdrop {
298	  position: fixed;
299	  inset: 0;
300	  background: rgba(13, 14, 31, 0.85);
301	  display: flex;
302	  align-items: center;
303	  justify-content: center;
304	  z-index: var(--z-modal);
305	  backdrop-filter: blur(2px);
306	}
307	
308	.pf-modal {
309	  background: var(--color-surface);
310	  border: 1px solid var(--color-border-strong);
311	  border-radius: var(--radius-lg);
312	  padding: var(--space-8);
313	  max-width: 480px;
314	  width: 90%;
315	  position: relative;
316	}
317	
318	/* Corner bracket decoration — drop inside any container */
319	.pf-corners::before,
320	.pf-corners::after,
321	.pf-corners > .pf-corner-bl,
322	.pf-corners > .pf-corner-br {
323	  content: '';
324	  position: absolute;
325	  width: 14px;
326	  height: 14px;
327	  pointer-events: none;
328	}
329	.pf-corners::before {
330	  top: 8px; left: 8px;
331	  border-top: 1px solid var(--color-accent);
332	  border-left: 1px solid var(--color-accent);
333	}
334	.pf-corners::after {
335	  top: 8px; right: 8px;
336	  border-top: 1px solid var(--color-accent);
337	  border-right: 1px solid var(--color-accent);
338	}
339	.pf-corners > .pf-corner-bl {
340	  bottom: 8px; left: 8px;
341	  border-bottom: 1px solid var(--color-accent);
342	  border-left: 1px solid var(--color-accent);
343	}
344	.pf-corners > .pf-corner-br {
345	  bottom: 8px; right: 8px;
346	  border-bottom: 1px solid var(--color-accent);
347	  border-right: 1px solid var(--color-accent);
348	}
349	
350	
351	/* --------------------------------------------------------------------------
352	   HUD BAR (progress / time bar)
353	   -------------------------------------------------------------------------- */
354	.pf-bar-track {
355	  height: 4px;
356	  background: rgba(255, 255, 255, 0.07);
357	  border-radius: 2px;
358	  overflow: hidden;
359	  margin-top: var(--space-2);
360	}
361	
362	.pf-bar-fill {
363	  height: 100%;
364	  border-radius: 2px;
365	  background: var(--color-purple-bright);
366	  transition: width 0.5s ease;
367	}
368	
369	.pf-bar-fill.accent   { background: var(--color-accent); }
370	.pf-bar-fill.danger   { background: var(--color-danger); }
371	.pf-bar-fill.success  { background: var(--color-success); }
372	.pf-bar-fill.warning  { background: var(--color-warning); }
373	
374	
375	/* --------------------------------------------------------------------------
376	   TERMINAL / COCKPIT INPUT BLOCK
377	   -------------------------------------------------------------------------- */
378	.pf-terminal {
379	  background: var(--color-well);
380	  border: 1px solid var(--color-border-strong);
381	  border-radius: var(--radius-md);
382	  overflow: hidden;
383	  font-family: var(--font-terminal);
384	}
385	
386	.pf-terminal-bar {
387	  background: rgba(107, 95, 212, 0.15);
388	  padding: 7px 12px;
389	  display: flex;
390	  align-items: center;
391	  gap: var(--space-2);
392	}
393	
394	.pf-terminal-dot {
395	  width: 8px; height: 8px;
396	  border-radius: 50%;
397	}
398	.pf-terminal-dot.red    { background: var(--color-danger); }
399	.pf-terminal-dot.yellow { background: var(--color-warning); }
400	.pf-terminal-dot.green  { background: var(--color-success); }
401	
402	.pf-terminal-title {
403	  font-size: var(--text-xs);
404	  letter-spacing: var(--tracking-wider);
405	  text-transform: uppercase;
406	  color: var(--color-text-muted);
407	  margin-left: var(--space-1);
408	}
409	
410	.pf-terminal-body {
411	  padding: var(--space-4);
412	  font-size: var(--text-sm);
413	  line-height: 1.9;
414	}
415	
416	.pf-terminal-prompt  { color: var(--color-purple-bright); }
417	.pf-terminal-cmd     { color: var(--color-accent); }
418	.pf-terminal-output  { color: var(--color-text-secondary); }
419	.pf-terminal-success { color: var(--color-success); }
420	.pf-terminal-error   { color: var(--color-danger); }
421	
422	/* Blinking cursor */
423	.pf-cursor {
424	  display: inline-block;
425	  width: 8px;
426	  height: 13px;
427	  background: var(--color-accent);
428	  vertical-align: -2px;
429	  animation: pf-blink 1s step-end infinite;
430	}
431	
432	@keyframes pf-blink { 50% { opacity: 0; } }
433	
434	/* Input field inside terminal */
435	.pf-terminal-input {
436	  background: transparent;
437	  border: none;
438	  outline: none;
439	  font-family: var(--font-terminal);
440	  font-size: var(--text-sm);
441	  color: var(--color-accent);
442	  caret-color: var(--color-accent);
443	  width: calc(100% - 16px);
444	}
445	
446	
447	/* --------------------------------------------------------------------------
448	   MISSION / SHIP REQUEST BLOCK
449	   -------------------------------------------------------------------------- */
450	.pf-mission {
451	  background: var(--color-surface);
452	  border: 1px solid var(--color-border);
453	  border-left: 3px solid var(--color-purple);
454	  border-radius: 0 var(--radius-md) var(--radius-md) 0;
455	  padding: 10px var(--space-4);
456	  font-family: var(--font-terminal);
457	  font-size: 11px;
458	  line-height: 1.8;
459	  color: var(--color-text-secondary);
460	}
461	
462	.pf-mission .keyword { color: var(--color-accent); font-weight: 700; }
463	.pf-mission .dim     { color: var(--color-text-muted); }
464	
465	
466	/* --------------------------------------------------------------------------
467	   LEADERBOARD
468	   -------------------------------------------------------------------------- */
469	.pf-lb-row {
470	  display: grid;
471	  grid-template-columns: 36px 1fr auto;
472	  align-items: center;
473	  gap: var(--space-3);
474	  padding: 10px 0;
475	  border-bottom: 1px solid rgba(107, 95, 212, 0.1);
476	}
477	
478	.pf-lb-row.you {
479	  background: rgba(107, 95, 212, 0.1);
480	  border-radius: var(--radius-sm);
481	  padding: 10px var(--space-2);
482	}
483	
484	.pf-lb-rank {
485	  font-family: var(--font-terminal);
486	  font-size: var(--text-sm);
487	  color: var(--color-text-muted);
488	  text-align: center;
489	}
490	
491	.pf-lb-rank.gold   { color: var(--color-warning); }
492	.pf-lb-rank.silver { color: #A0A4B0; }
493	.pf-lb-rank.bronze { color: #CD8B5A; }
494	
495	.pf-lb-name  {
496	  font-family: var(--font-ui);
497	  font-size: var(--text-base);
498	  font-weight: 500;
499	  color: var(--color-text-primary);
500	}
501	
502	.pf-lb-name.you { color: var(--color-accent); }
503	
504	.pf-lb-score {
505	  font-family: var(--font-terminal);
506	  font-size: var(--text-base);
507	  font-weight: 700;
508	  color: var(--color-accent);
509	  text-align: right;
510	}
511	
512	.pf-lb-level {
513	  font-family: var(--font-terminal);
514	  font-size: var(--text-xs);
515	  color: var(--color-purple-bright);
516	  text-transform: uppercase;
517	  letter-spacing: var(--tracking-normal);
518	}
519	
520	
521	/* --------------------------------------------------------------------------
522	   BADGES & PILLS
523	   -------------------------------------------------------------------------- */
524	.pf-badge {
525	  display: inline-flex;
526	  align-items: center;
527	  gap: var(--space-1);
528	  font-family: var(--font-terminal);
529	  font-size: var(--text-xs);
530	  letter-spacing: var(--tracking-normal);
531	  text-transform: uppercase;
532	  padding: 3px 8px;
533	  border-radius: var(--radius-sm);
534	  background: rgba(107, 95, 212, 0.15);
535	  color: var(--color-purple-bright);
536	  border: 1px solid var(--color-border);
537	}
538	
539	.pf-badge.accent {
540	  background: rgba(0, 229, 196, 0.1);
541	  color: var(--color-accent);
542	  border-color: rgba(0, 229, 196, 0.3);
543	}
544	
545	.pf-badge.danger {
546	  background: rgba(226, 75, 74, 0.1);
547	  color: var(--color-danger);
548	  border-color: rgba(226, 75, 74, 0.3);
549	}
550	
551	/* Live dot */
552	.pf-live-dot {
553	  width: 6px; height: 6px;
554	  border-radius: 50%;
555	  background: var(--color-accent);
556	  display: inline-block;
557	  animation: pf-pulse 2s ease-in-out infinite;
558	}
559	
560	@keyframes pf-pulse {
561	  0%, 100% { opacity: 1; }
562	  50%       { opacity: 0.25; }
563	}
564	
565	
566	/* --------------------------------------------------------------------------
567	   DIVIDERS
568	   -------------------------------------------------------------------------- */
569	.pf-divider {
570	  display: flex;
571	  align-items: center;
572	  gap: var(--space-3);
573	  color: var(--color-text-muted);
574	  font-family: var(--font-terminal);
575	  font-size: var(--text-xs);
576	  letter-spacing: var(--tracking-wider);
577	  text-transform: uppercase;
578	}
579	
580	.pf-divider::before,
581	.pf-divider::after {
582	  content: '';
583	  flex: 1;
584	  height: 1px;
585	  background: var(--color-border);
586	}
587	
588	
589	/* --------------------------------------------------------------------------
590	   SPLASH / TITLE SCREEN
591	   -------------------------------------------------------------------------- */
592	.pf-splash {
593	  position: relative;
594	  display: flex;
595	  flex-direction: column;
596	  align-items: center;
597	  justify-content: center;
598	  gap: var(--space-4);
599	  padding: var(--space-10);
600	  text-align: center;
601	  overflow: hidden;
602	}
603	
604	/* Subtitle eyebrow above title */
605	.pf-splash-eyebrow {
606	  font-family: var(--font-terminal);
607	  font-size: var(--text-xs);
608	  letter-spacing: var(--tracking-wider);
609	  text-transform: uppercase;
610	  color: var(--color-purple-bright);
611	}
612	
613	/* Brand attribution line */
614	.pf-splash-brand {
615	  font-family: var(--font-terminal);
616	  font-size: var(--text-xs);
617	  letter-spacing: var(--tracking-wide);
618	  text-transform: uppercase;
619	  color: var(--color-text-muted);
620	}
621	
622	.pf-splash-brand strong { color: rgba(240, 238, 248, 0.6); }
623	
624	/* Scanline footer */
625	.pf-scanline {
626	  position: absolute;
627	  bottom: var(--space-5);
628	  left: 0; right: 0;
629	  display: flex;
630	  align-items: center;
631	  gap: var(--space-3);
632	  padding: 0 var(--space-6);
633	  opacity: 0.35;
634	  pointer-events: none;
635	}
636	
637	.pf-scanline::before,
638	.pf-scanline::after {
639	  content: '';
640	  flex: 1;
641	  height: 1px;
642	  background: var(--color-border);
643	}
644	
645	.pf-scanline-text {
646	  font-family: var(--font-terminal);
647	  font-size: 9px;
648	  letter-spacing: var(--tracking-wider);
649	  color: var(--color-purple-bright);
650	  white-space: nowrap;
651	}
652	
653	
654	/* --------------------------------------------------------------------------
655	   SCREEN ANNOUNCEMENT (level intro overlays)
656	   e.g. "SIGNAL LOST · LEVEL 1", "ARCHIVE SURFACED · LEVEL 2"
657	   -------------------------------------------------------------------------- */
658	.pf-announce {
659	  position: fixed;
660	  inset: 0;
661	  background: rgba(13, 14, 31, 0.92);
662	  display: flex;
663	  flex-direction: column;
664	  align-items: center;
665	  justify-content: center;
666	  gap: var(--space-4);
667	  z-index: var(--z-overlay);
668	  text-align: center;
669	}
670	
671	.pf-announce-title {
672	  font-family: var(--font-terminal);
673	  font-size: var(--text-2xl);
674	  font-weight: 700;
675	  letter-spacing: var(--tracking-wide);
676	  text-transform: uppercase;
677	  color: var(--color-text-primary);
678	}
679	
680	.pf-announce-sub {
681	  font-family: var(--font-terminal);
682	  font-size: var(--text-sm);
683	  letter-spacing: var(--tracking-wider);
684	  text-transform: uppercase;
685	  color: var(--color-purple-bright);
686	}
687	
688	.pf-announce-hint {
689	  font-family: var(--font-terminal);
690	  font-size: var(--text-sm);
691	  color: var(--color-text-muted);
692	  margin-top: var(--space-4);
693	  animation: pf-pulse 1.5s ease-in-out infinite;
694	}
695	
696	
697	/* --------------------------------------------------------------------------
698	   MENU LIST (main menu / options)
699	   -------------------------------------------------------------------------- */
700	.pf-menu {
701	  list-style: none;
702	  display: flex;
703	  flex-direction: column;
704	  gap: var(--space-2);
705	}
706	
707	.pf-menu-item {
708	  font-family: var(--font-terminal);
709	  font-size: var(--text-md);
710	  font-weight: 700;
711	  letter-spacing: var(--tracking-wide);
712	  text-transform: uppercase;
713	  color: var(--color-text-secondary);
714	  padding: var(--space-3) var(--space-4);
715	  border-radius: var(--radius-sm);
716	  cursor: pointer;
717	  transition: color var(--ease-fast), background var(--ease-fast);
718	  border: 1px solid transparent;
719	  user-select: none;
720	}
721	
722	.pf-menu-item:hover,
723	.pf-menu-item.selected {
724	  color: var(--color-text-primary);
725	  background: rgba(107, 95, 212, 0.12);
726	  border-color: var(--color-border);
727	}
728	
729	.pf-menu-item.selected::before {
730	  content: '▶ ';
731	  color: var(--color-accent);
732	}
733	
734	
735	/* --------------------------------------------------------------------------
736	   UTILITY CLASSES
737	   -------------------------------------------------------------------------- */
738	.pf-text-accent   { color: var(--color-accent) !important; }
739	.pf-text-purple   { color: var(--color-purple-bright) !important; }
740	.pf-text-muted    { color: var(--color-text-muted) !important; }
741	.pf-text-success  { color: var(--color-success) !important; }
742	.pf-text-danger   { color: var(--color-danger) !important; }
743	.pf-text-warning  { color: var(--color-warning) !important; }
744	
745	.pf-uppercase { text-transform: uppercase; letter-spacing: var(--tracking-wide); }
746	.pf-mono      { font-family: var(--font-terminal) !important; }
747	
748	.pf-flex      { display: flex; }
749	.pf-flex-col  { display: flex; flex-direction: column; }
750	.pf-items-center { align-items: center; }
751	.pf-justify-between { justify-content: space-between; }
752	.pf-gap-1 { gap: var(--space-1); }
753	.pf-gap-2 { gap: var(--space-2); }
754	.pf-gap-3 { gap: var(--space-3); }
755	.pf-gap-4 { gap: var(--space-4); }
756	
757	.pf-mt-2 { margin-top: var(--space-2); }
758	.pf-mt-4 { margin-top: var(--space-4); }
759	.pf-mt-6 { margin-top: var(--space-6); }
760	
761	.pf-sr-only {
762	  position: absolute;
763	  width: 1px; height: 1px;
764	  overflow: hidden;
765	  clip: rect(0,0,0,0);
766	  white-space: nowrap;
767	}
768	
769	
770	/* --------------------------------------------------------------------------
771	   THREE.JS CANVAS INTEGRATION NOTES
772	   (comments only — not CSS, for the dev reading this file)
773	
774	   1. PLANET MATERIAL
775	      Change your sphere material to:
776	        new THREE.MeshStandardMaterial({
777	          color: 0x534AB7,
778	          emissive: 0x1A1B3E,
779	          roughness: 0.7,
780	          metalness: 0.1,
781	        })
782	
783	   2. STAR FIELD (THREE.Points)
784	      Use white with low opacity — the dark bg does the work:
785	        new THREE.PointsMaterial({ color: 0xffffff, size: 0.08, transparent: true, opacity: 0.55 })
786	
787	   3. CHECKPOINT BEAMS
788	      The gold/accent beam color:  0x00E5C4  (--color-accent)
789	      Secondary / inactive:        0x6B5FD4  (--color-purple)
790	
791	   4. GRID / TERRAIN WIREFRAME
792	      Use: 0x2B2D6E (--color-purple-glow) at low opacity for ground grid lines
793	
794	   5. HTML OVERLAY MOUNTING
795	      Mount your UI overlay as a <div class="pf-ui"> positioned
796	      absolute over the <canvas>. All classes above apply inside it.
797	      Example structure:
798	        <div style="position:relative; width:100vw; height:100vh;">
799	          <canvas id="game-canvas"></canvas>
800	          <div class="pf-ui" style="position:absolute;inset:0;pointer-events:none;">
801	            <div class="pf-hud" style="pointer-events:auto;">...</div>
802	          </div>
803	        </div>
804	   -------------------------------------------------------------------------- */
805

