/* ==========================================================================
   PLANETFALL × ENTIRE.IO — UI THEME
   Drop this file into your project and import it before your game styles.
   All game UI (menus, HUD, terminal, overlays) inherits from these tokens.
   ========================================================================== */

/* --------------------------------------------------------------------------
   FONTS — add this @import at the very top of your main CSS entry point
   -------------------------------------------------------------------------- */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=Space+Mono:ital,wght@0,400;0,700;1,400&display=swap');

/* --------------------------------------------------------------------------
   TOKENS
   -------------------------------------------------------------------------- */
:root {

  /* Palette ---------------------------------------------------------------- */
  --color-bg:             #0D0E1F;   /* page / canvas backdrop             */
  --color-surface:        #12132A;   /* cards, HUD panels, menu backgrounds */
  --color-surface-raised: #1A1B3E;   /* elevated surfaces, dropdowns        */
  --color-well:           #080910;   /* terminal, deeply inset areas        */

  --color-purple:         #6B5FD4;   /* primary action, borders, rings      */
  --color-purple-bright:  #8B7FE8;   /* secondary labels, icons             */
  --color-purple-dim:     #534AB7;   /* hover state for purple elements     */
  --color-purple-glow:    #2B2D6E;   /* subtle backgrounds, selection bg    */

  --color-accent:         #00E5C4;   /* timers, CTAs, beam highlights, live */
  --color-accent-dim:     #00B39A;   /* hover state for accent elements     */

  --color-text-primary:   #F0EEF8;   /* headings, values, active labels     */
  --color-text-secondary: rgba(240, 238, 248, 0.6);  /* body, descriptions  */
  --color-text-muted:     rgba(240, 238, 248, 0.3);  /* hints, timestamps   */

  --color-success:        #6EE7B7;   /* correct input, transmission OK      */
  --color-warning:        #F5C440;   /* gold rank, time running low         */
  --color-danger:         #E24B4A;   /* time up, system error               */

  --color-border:         rgba(107, 95, 212, 0.25);  /* default borders     */
  --color-border-strong:  rgba(107, 95, 212, 0.5);   /* focused / hover     */
  --color-border-accent:  rgba(0, 229, 196, 0.4);    /* accent-adjacent     */

  /* Typography ------------------------------------------------------------- */
  --font-display: 'Space Mono', 'Courier New', monospace;
  --font-ui:      'Space Grotesk', system-ui, sans-serif;
  --font-terminal:'Space Mono', 'Courier New', monospace;

  /* Type scale */
  --text-xs:   10px;
  --text-sm:   12px;
  --text-base: 14px;
  --text-md:   16px;
  --text-lg:   20px;
  --text-xl:   28px;
  --text-2xl:  40px;
  --text-3xl:  56px;

  /* Letter spacing */
  --tracking-tight:  0.02em;
  --tracking-normal: 0.05em;
  --tracking-wide:   0.12em;
  --tracking-wider:  0.2em;

  /* Spacing ---------------------------------------------------------------- */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;

  /* Radii ------------------------------------------------------------------ */
  --radius-sm: 2px;   /* buttons, tags — sharp/angular feel  */
  --radius-md: 4px;   /* cards, panels                       */
  --radius-lg: 8px;   /* modals, larger containers           */
  --radius-pill: 20px;/* badges                              */

  /* Transitions ------------------------------------------------------------ */
  --ease-fast:   0.15s ease;
  --ease-normal: 0.25s ease;
  --ease-slow:   0.4s ease;

  /* Z-layers --------------------------------------------------------------- */
  --z-hud:     10;
  --z-overlay: 20;
  --z-modal:   30;
  --z-top:     40;
}


/* --------------------------------------------------------------------------
   BASE RESET — scoped to the game UI root
   Apply class="pf-ui" to your top-level overlay container
   -------------------------------------------------------------------------- */
.pf-ui,
.pf-ui * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.pf-ui {
  font-family: var(--font-ui);
  font-size: var(--text-base);
  color: var(--color-text-primary);
  background: transparent;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}


/* --------------------------------------------------------------------------
   TYPOGRAPHY UTILITIES
   -------------------------------------------------------------------------- */

/* Display — game title, level announcements */
.pf-title {
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--color-text-primary);
  line-height: 1;
}

.pf-title .accent { color: var(--color-accent); }

/* Section headers / screen names */
.pf-heading {
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--color-text-primary);
}

/* HUD labels — TIME REMAINING, SIGNAL STRENGTH etc */
.pf-label {
  font-family: var(--font-display);
  font-size: var(--text-xs);
  font-weight: 400;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-purple-bright);
}

/* HUD values — the big number */
.pf-value {
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1;
}

.pf-value.accent { color: var(--color-accent); }

/* Body text */
.pf-body {
  font-family: var(--font-ui);
  font-size: var(--text-base);
  color: var(--color-text-secondary);
  line-height: 1.7;
}

/* Muted / hints */
.pf-muted {
  font-family: var(--font-display);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  letter-spacing: var(--tracking-normal);
}

/* Terminal text */
.pf-mono {
  font-family: var(--font-terminal);
  font-size: var(--text-sm);
  line-height: 1.9;
}


/* --------------------------------------------------------------------------
   BUTTONS
   -------------------------------------------------------------------------- */

/* Primary — START GAME, CONFIRM, TRANSMIT */
.pf-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-display);
  font-size: var(--text-sm);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: 13px 32px;
  background: var(--color-purple);
  color: var(--color-text-primary);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--ease-fast);
  /* angled clip — signature game-button shape */
  clip-path: polygon(10px 0%, 100% 0%, calc(100% - 10px) 100%, 0% 100%);
  white-space: nowrap;
  user-select: none;
}

.pf-btn:hover  { background: var(--color-purple-bright); }
.pf-btn:active { background: var(--color-purple-dim); transform: scale(0.98); }

/* Secondary — LEADERBOARD, BACK, OPTIONS */
.pf-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-display);
  font-size: var(--text-sm);
  font-weight: 400;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: 12px 24px;
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--ease-fast), color var(--ease-fast);
  white-space: nowrap;
  user-select: none;
}

.pf-btn-ghost:hover  { background: rgba(0, 229, 196, 0.08); }
.pf-btn-ghost:active { background: rgba(0, 229, 196, 0.15); transform: scale(0.98); }

/* Danger — TIME'S UP, ABORT */
.pf-btn-danger {
  background: var(--color-danger);
  color: #fff;
}
.pf-btn-danger:hover { background: #f06060; }


/* --------------------------------------------------------------------------
   PANELS & CARDS
   -------------------------------------------------------------------------- */

/* General surface panel */
.pf-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  position: relative;
}

/* Top-accent stripe — use with .pf-panel */
.pf-panel::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  background: var(--color-purple);
}

.pf-panel.accent-top::before { background: var(--color-accent); }
.pf-panel.no-stripe::before  { display: none; }

/* HUD card — compact stat tile */
.pf-hud-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  position: relative;
  overflow: hidden;
}

.pf-hud-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: var(--color-purple);
}

.pf-hud-card.critical::before { background: var(--color-accent); }

/* Modal / full overlay */
.pf-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(13, 14, 31, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: var(--z-modal);
  backdrop-filter: blur(2px);
}

.pf-modal {
  background: var(--color-surface);
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  max-width: 480px;
  width: 90%;
  position: relative;
}

/* Corner bracket decoration — drop inside any container */
.pf-corners::before,
.pf-corners::after,
.pf-corners > .pf-corner-bl,
.pf-corners > .pf-corner-br {
  content: '';
  position: absolute;
  width: 14px;
  height: 14px;
  pointer-events: none;
}
.pf-corners::before {
  top: 8px; left: 8px;
  border-top: 1px solid var(--color-accent);
  border-left: 1px solid var(--color-accent);
}
.pf-corners::after {
  top: 8px; right: 8px;
  border-top: 1px solid var(--color-accent);
  border-right: 1px solid var(--color-accent);
}
.pf-corners > .pf-corner-bl {
  bottom: 8px; left: 8px;
  border-bottom: 1px solid var(--color-accent);
  border-left: 1px solid var(--color-accent);
}
.pf-corners > .pf-corner-br {
  bottom: 8px; right: 8px;
  border-bottom: 1px solid var(--color-accent);
  border-right: 1px solid var(--color-accent);
}


/* --------------------------------------------------------------------------
   HUD BAR (progress / time bar)
   -------------------------------------------------------------------------- */
.pf-bar-track {
  height: 4px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 2px;
  overflow: hidden;
  margin-top: var(--space-2);
}

.pf-bar-fill {
  height: 100%;
  border-radius: 2px;
  background: var(--color-purple-bright);
  transition: width 0.5s ease;
}

.pf-bar-fill.accent   { background: var(--color-accent); }
.pf-bar-fill.danger   { background: var(--color-danger); }
.pf-bar-fill.success  { background: var(--color-success); }
.pf-bar-fill.warning  { background: var(--color-warning); }


/* --------------------------------------------------------------------------
   TERMINAL / COCKPIT INPUT BLOCK
   -------------------------------------------------------------------------- */
.pf-terminal {
  background: var(--color-well);
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-md);
  overflow: hidden;
  font-family: var(--font-terminal);
}

.pf-terminal-bar {
  background: rgba(107, 95, 212, 0.15);
  padding: 7px 12px;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.pf-terminal-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
}
.pf-terminal-dot.red    { background: var(--color-danger); }
.pf-terminal-dot.yellow { background: var(--color-warning); }
.pf-terminal-dot.green  { background: var(--color-success); }

.pf-terminal-title {
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-left: var(--space-1);
}

.pf-terminal-body {
  padding: var(--space-4);
  font-size: var(--text-sm);
  line-height: 1.9;
}

.pf-terminal-prompt  { color: var(--color-purple-bright); }
.pf-terminal-cmd     { color: var(--color-accent); }
.pf-terminal-output  { color: var(--color-text-secondary); }
.pf-terminal-success { color: var(--color-success); }
.pf-terminal-error   { color: var(--color-danger); }

/* Blinking cursor */
.pf-cursor {
  display: inline-block;
  width: 8px;
  height: 13px;
  background: var(--color-accent);
  vertical-align: -2px;
  animation: pf-blink 1s step-end infinite;
}

@keyframes pf-blink { 50% { opacity: 0; } }

/* Input field inside terminal */
.pf-terminal-input {
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--font-terminal);
  font-size: var(--text-sm);
  color: var(--color-accent);
  caret-color: var(--color-accent);
  width: calc(100% - 16px);
}


/* --------------------------------------------------------------------------
   MISSION / SHIP REQUEST BLOCK
   -------------------------------------------------------------------------- */
.pf-mission {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-left: 3px solid var(--color-purple);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: 10px var(--space-4);
  font-family: var(--font-terminal);
  font-size: 11px;
  line-height: 1.8;
  color: var(--color-text-secondary);
}

.pf-mission .keyword { color: var(--color-accent); font-weight: 700; }
.pf-mission .dim     { color: var(--color-text-muted); }


/* --------------------------------------------------------------------------
   LEADERBOARD
   -------------------------------------------------------------------------- */
.pf-lb-row {
  display: grid;
  grid-template-columns: 36px 1fr auto;
  align-items: center;
  gap: var(--space-3);
  padding: 10px 0;
  border-bottom: 1px solid rgba(107, 95, 212, 0.1);
}

.pf-lb-row.you {
  background: rgba(107, 95, 212, 0.1);
  border-radius: var(--radius-sm);
  padding: 10px var(--space-2);
}

.pf-lb-rank {
  font-family: var(--font-terminal);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  text-align: center;
}

.pf-lb-rank.gold   { color: var(--color-warning); }
.pf-lb-rank.silver { color: #A0A4B0; }
.pf-lb-rank.bronze { color: #CD8B5A; }

.pf-lb-name  {
  font-family: var(--font-ui);
  font-size: var(--text-base);
  font-weight: 500;
  color: var(--color-text-primary);
}

.pf-lb-name.you { color: var(--color-accent); }

.pf-lb-score {
  font-family: var(--font-terminal);
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--color-accent);
  text-align: right;
}

.pf-lb-level {
  font-family: var(--font-terminal);
  font-size: var(--text-xs);
  color: var(--color-purple-bright);
  text-transform: uppercase;
  letter-spacing: var(--tracking-normal);
}


/* --------------------------------------------------------------------------
   BADGES & PILLS
   -------------------------------------------------------------------------- */
.pf-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  font-family: var(--font-terminal);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-normal);
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  background: rgba(107, 95, 212, 0.15);
  color: var(--color-purple-bright);
  border: 1px solid var(--color-border);
}

.pf-badge.accent {
  background: rgba(0, 229, 196, 0.1);
  color: var(--color-accent);
  border-color: rgba(0, 229, 196, 0.3);
}

.pf-badge.danger {
  background: rgba(226, 75, 74, 0.1);
  color: var(--color-danger);
  border-color: rgba(226, 75, 74, 0.3);
}

/* Live dot */
.pf-live-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  display: inline-block;
  animation: pf-pulse 2s ease-in-out infinite;
}

@keyframes pf-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.25; }
}


/* --------------------------------------------------------------------------
   DIVIDERS
   -------------------------------------------------------------------------- */
.pf-divider {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  color: var(--color-text-muted);
  font-family: var(--font-terminal);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
}

.pf-divider::before,
.pf-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--color-border);
}


/* --------------------------------------------------------------------------
   SPLASH / TITLE SCREEN
   -------------------------------------------------------------------------- */
.pf-splash {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  padding: var(--space-10);
  text-align: center;
  overflow: hidden;
}

/* Subtitle eyebrow above title */
.pf-splash-eyebrow {
  font-family: var(--font-terminal);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-purple-bright);
}

/* Brand attribution line */
.pf-splash-brand {
  font-family: var(--font-terminal);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.pf-splash-brand strong { color: rgba(240, 238, 248, 0.6); }

/* Scanline footer */
.pf-scanline {
  position: absolute;
  bottom: var(--space-5);
  left: 0; right: 0;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 0 var(--space-6);
  opacity: 0.35;
  pointer-events: none;
}

.pf-scanline::before,
.pf-scanline::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--color-border);
}

.pf-scanline-text {
  font-family: var(--font-terminal);
  font-size: 9px;
  letter-spacing: var(--tracking-wider);
  color: var(--color-purple-bright);
  white-space: nowrap;
}


/* --------------------------------------------------------------------------
   SCREEN ANNOUNCEMENT (level intro overlays)
   e.g. "SIGNAL LOST · LEVEL 1", "ARCHIVE SURFACED · LEVEL 2"
   -------------------------------------------------------------------------- */
.pf-announce {
  position: fixed;
  inset: 0;
  background: rgba(13, 14, 31, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  z-index: var(--z-overlay);
  text-align: center;
}

.pf-announce-title {
  font-family: var(--font-terminal);
  font-size: var(--text-2xl);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--color-text-primary);
}

.pf-announce-sub {
  font-family: var(--font-terminal);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-purple-bright);
}

.pf-announce-hint {
  font-family: var(--font-terminal);
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  margin-top: var(--space-4);
  animation: pf-pulse 1.5s ease-in-out infinite;
}


/* --------------------------------------------------------------------------
   MENU LIST (main menu / options)
   -------------------------------------------------------------------------- */
.pf-menu {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.pf-menu-item {
  font-family: var(--font-terminal);
  font-size: var(--text-md);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--color-text-secondary);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: color var(--ease-fast), background var(--ease-fast);
  border: 1px solid transparent;
  user-select: none;
}

.pf-menu-item:hover,
.pf-menu-item.selected {
  color: var(--color-text-primary);
  background: rgba(107, 95, 212, 0.12);
  border-color: var(--color-border);
}

.pf-menu-item.selected::before {
  content: '▶ ';
  color: var(--color-accent);
}


/* --------------------------------------------------------------------------
   UTILITY CLASSES
   -------------------------------------------------------------------------- */
.pf-text-accent   { color: var(--color-accent) !important; }
.pf-text-purple   { color: var(--color-purple-bright) !important; }
.pf-text-muted    { color: var(--color-text-muted) !important; }
.pf-text-success  { color: var(--color-success) !important; }
.pf-text-danger   { color: var(--color-danger) !important; }
.pf-text-warning  { color: var(--color-warning) !important; }

.pf-uppercase { text-transform: uppercase; letter-spacing: var(--tracking-wide); }
.pf-mono      { font-family: var(--font-terminal) !important; }

.pf-flex      { display: flex; }
.pf-flex-col  { display: flex; flex-direction: column; }
.pf-items-center { align-items: center; }
.pf-justify-between { justify-content: space-between; }
.pf-gap-1 { gap: var(--space-1); }
.pf-gap-2 { gap: var(--space-2); }
.pf-gap-3 { gap: var(--space-3); }
.pf-gap-4 { gap: var(--space-4); }

.pf-mt-2 { margin-top: var(--space-2); }
.pf-mt-4 { margin-top: var(--space-4); }
.pf-mt-6 { margin-top: var(--space-6); }

.pf-sr-only {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}


/* --------------------------------------------------------------------------
   THREE.JS CANVAS INTEGRATION NOTES
   (comments only — not CSS, for the dev reading this file)

   1. PLANET MATERIAL
      Change your sphere material to:
        new THREE.MeshStandardMaterial({
          color: 0x534AB7,
          emissive: 0x1A1B3E,
          roughness: 0.7,
          metalness: 0.1,
        })

   2. STAR FIELD (THREE.Points)
      Use white with low opacity — the dark bg does the work:
        new THREE.PointsMaterial({ color: 0xffffff, size: 0.08, transparent: true, opacity: 0.55 })

   3. CHECKPOINT BEAMS
      The gold/accent beam color:  0x00E5C4  (--color-accent)
      Secondary / inactive:        0x6B5FD4  (--color-purple)

   4. GRID / TERRAIN WIREFRAME
      Use: 0x2B2D6E (--color-purple-glow) at low opacity for ground grid lines

   5. HTML OVERLAY MOUNTING
      Mount your UI overlay as a <div class="pf-ui"> positioned
      absolute over the <canvas>. All classes above apply inside it.
      Example structure:
        <div style="position:relative; width:100vw; height:100vh;">
          <canvas id="game-canvas"></canvas>
          <div class="pf-ui" style="position:absolute;inset:0;pointer-events:none;">
            <div class="pf-hud" style="pointer-events:auto;">...</div>
          </div>
        </div>
   -------------------------------------------------------------------------- */

